function cancelDraft(say=false){draft=null;draftOriginal=null;selected=null;$('annotationEditor').classList.add('hidden');$('annotationEditor').innerHTML='';queueDraw();if(say)toast('已取消编辑，原图与已保存标注未变化。')}
function saveAnnotation(){if(!draft||job)return;const obj=clone(draft);obj.label=obj.label.trim()||obj.type;obj.status='confirmed';obj.rect=obj.rect.map(v=>Math.round(v*10)/10);const id=obj.id,existing=!!draftOriginal,previous=head().id;const ok=commit(existing?'复核并修正 '+obj.label:'补充 '+obj.label,fs=>{const items=fs[activeFloor].items,idx=items.findIndex(o=>o.id===id);if(idx>=0)items[idx]=obj;else items.push(obj)});if(!ok)return;cancelDraft(false);tool='select';document.querySelectorAll('[data-tool]').forEach(el=>el.classList.toggle('active',el.dataset.tool==='select'));queueDraw();toast(`${existing?'已确认':'已保存'}「${obj.label}」 · 新版本 ${head().id}`);event(p(),'annotation.saved',existing?'确认识别对象':'保存人工补充',{id,floor:activeFloor,rect:obj.rect,base:previous,newRevision:head().id});if(drawer)renderDrawer()}
function deleteAnnotation(){if(!draftOriginal||job)return;const id=draftOriginal.id,label=draftOriginal.label;commit('删除标注 '+label,fs=>{fs[activeFloor].items=fs[activeFloor].items.filter(o=>o.id!==id)});cancelDraft(false);toast('标注已移除，可撤销；原图没有变化。')}
function closePop(){const was=$('popoverRoot').children.length;$('popoverRoot').innerHTML='';if(was&&popFocus?.isConnected)popFocus.focus({preventScroll:true});popFocus=null}
function pop(anchor,html){const same=$('popoverRoot').dataset.owner===anchor.id&&$('popoverRoot').children.length;closePop();if(same)return;popFocus=anchor;$('popoverRoot').dataset.owner=anchor.id;$('popoverRoot').innerHTML=`<div class="pop-menu" role="dialog" aria-label="操作菜单">${html}</div>`;const el=$('popoverRoot').firstElementChild,b=anchor.getBoundingClientRect();el.style.left=clamp(b.left,12,window.innerWidth-el.offsetWidth-12)+'px';el.style.top=Math.min(b.bottom+7,window.innerHeight-el.offsetHeight-12)+'px';el.querySelector('button')?.focus({preventScroll:true})}
function projectPop(){pop($('projectMenu'),'<div class="menu-heading">切换项目</div>'+state.projects.map(pr=>`<button class="menu-option ${pr.id===activeId?'active':''}" data-pr="${pr.id}">${ic('building')}<span><strong>${esc(pr.name)}</strong><small>${Object.keys(head(pr).floors).length} 个楼层 · ${head(pr).id}</small></span>${pr.id===activeId?'<span class="end">当前</span>':''}</button>`).join('')+`<div class="menu-line"></div><button class="menu-option" id="allProjects">${ic('dotgrid')}所有项目</button>`);document.querySelectorAll('[data-pr]').forEach(b=>b.onclick=()=>enterProject(b.dataset.pr));if($('allProjects'))$('allProjects').onclick=goHome}
function floorPop(){pop($('floorBtn'),'<div class="menu-heading">当前版本的图纸</div>'+Object.entries(head().floors).map(([id,f])=>`<button class="menu-option ${id===activeFloor?'active':''}" data-fid="${id}">${ic('layers')}<span><strong>${esc(f.label)} · ${esc(f.name)}</strong><small>${f.items.length} 个标注 · ${f.items.filter(o=>o.status==='pending').length} 处待复核</small></span>${id===activeFloor?'<span class="end">当前</span>':''}</button>`).join('')+`<div class="menu-line"></div><button class="menu-option" id="manageFloors">${ic('upload')}导入 / 管理图纸</button>`);document.querySelectorAll('[data-fid]').forEach(b=>b.onclick=()=>switchFloor(b.dataset.fid));if($('manageFloors'))$('manageFloors').onclick=()=>{closePop();openSources()}}
function morePop(){pop($('moreBtn'),`<div class="menu-heading">项目操作</div><button class="menu-option" id="moreUpload">${ic('upload')}导入 / 管理图纸</button><button class="menu-option" id="moreObjects">${ic('scan')}全部识别对象</button><button class="menu-option" id="moreResult">${ic('cube')}本版本的演示成果</button><div class="menu-line"></div><button class="menu-option" id="moreExport">${ic('save')}导出标注工程 JSON</button><button class="menu-option" id="moreImport">${ic('upload')}导入标注工程 JSON</button><button class="menu-option" id="moreOverlay">${ic('download')}导出复核标注 PNG</button><button class="menu-option" id="moreEvents">${ic('log')}查看过程记录</button><button class="menu-option" id="moreHelp">${ic('help')}快捷键与原型边界</button>`);const actions={moreUpload:openSources,moreObjects:()=>openDrawer('objects'),moreResult:openResults,moreExport:exportProject,moreImport:()=>{if(job){toast('请先完成流程演示。',true);return}guardDraft(()=>$('projectInput').click())},moreOverlay:exportOverlay,moreEvents:()=>openDrawer('audit'),moreHelp:help};for(const [id,fn] of Object.entries(actions))if($(id))$(id).onclick=()=>{closePop();fn()}}
function openDrawer(kind){guardDraft(()=>{closePop();if(drawer===kind){closeDrawer();return}drawer=kind;$('sideDrawer').classList.remove('hidden');renderDrawer();$('historyBtn').classList.toggle('active',['history','audit'].includes(kind));requestAnimationFrame(resize)})}
function closeDrawer(){drawer=null;$('sideDrawer').classList.add('hidden');$('sideDrawer').innerHTML='';$('historyBtn').classList.remove('active');requestAnimationFrame(resize)}
function renderDrawer(){if(!drawer||!p())return;const pr=p(),h=head(),kind=drawer,titles={issues:'待复核问题',objects:'识别对象',history:'版本与过程',audit:'版本与过程'};let content='';if(kind==='issues'||kind==='objects'){const all=allItems(),filtered=kind==='issues'?all.filter(o=>o.status==='pending'):all;content=`<div class="drawer-section">${kind==='issues'?'仅显示需要确认的预设候选':'当前各楼层标注 · 点击查看原图位置'}</div>`;let last='';for(const o of filtered){if(last!==o.floorId){content+=`<div class="drawer-section" style="margin-top:18px">${esc(h.floors[o.floorId].label)} / ${esc(h.floors[o.floorId].name)}</div>`;last=o.floorId}content+=`<button class="object-row ${o.id===selected&&o.floorId===activeFloor?'active':''}" data-select-object="${o.id}" data-object-floor="${o.floorId}"><i class="indicator ${o.status==='pending'?'pending':o.source==='manual'?'manual':''}"></i><span><strong>${esc(o.label||o.type)}</strong><small>${o.source==='manual'?'人工补充':'预设识别候选'} · ${esc(o.type)}</small></span><span class="end">${o.status==='pending'?'待复核':o.status==='confirmed'?'已确认':'候选'}</span></button>`}if(!filtered.length)content='<div class="drawer-empty">'+ic('check')+'<br>当前没有待复核问题。<br>仍可在原图上补充遗漏对象。</div>';if(kind==='issues')content+=`<button class="textbtn" id="seeAllObjects">查看全部 ${all.length} 个标注 ${ic('arrow')}</button>`}
if(kind==='history'){content=pr.versions.slice().reverse().map(r=>`<div class="history-entry"><div class="between"><strong>${r.id} · ${esc(r.title)}</strong>${r.id===h.id?'<span class="subtle-badge">当前</span>':''}</div><p>${r.parent?'来源 '+r.parent:'初始版本'}${r.restoredFrom?' · 恢复自 '+r.restoredFrom:''}<br>${Object.values(r.floors).reduce((n,f)=>n+f.items.length,0)} 个标注 · 原图不变</p><small>${stamp(r.created)}</small>${r.id!==h.id?`<br><button class="textbtn" data-restore="${r.id}">查看并恢复 ${ic('arrow')}</button>`:''}</div>`).join('')}
if(kind==='audit'){content=pr.events.slice().reverse().map(e=>`<div class="audit-item"><time>${stamp(e.time)}</time><span>${esc(e.text)}</span><details><summary>过程详情</summary><pre>${esc(JSON.stringify(e.detail,null,2))}</pre></details></div>`).join('')}
$('sideDrawer').innerHTML=`<div class="drawer-head"><div class="between"><h3>${titles[kind]}</h3><button class="iconbtn" id="closeDrawer" aria-label="收起侧面板">${ic('close')}</button></div><p>${kind==='issues'?'点击问题，只在需要时展开编辑表单。':kind==='objects'?'框是证据区域，不等于已经生成建筑构件。':'恢复会追加新版本，不删除历史。'}</p>${['history','audit'].includes(kind)?`<div class="drawer-tabs"><button class="${kind==='history'?'active':''}" id="historyTab">版本历史</button><button class="${kind==='audit'?'active':''}" id="auditTab">过程记录</button></div>`:''}</div><div class="drawer-content">${content}</div>`;$('closeDrawer').onclick=closeDrawer;document.querySelectorAll('[data-select-object]').forEach(b=>b.onclick=()=>selectObject(b.dataset.selectObject,b.dataset.objectFloor));if($('seeAllObjects'))$('seeAllObjects').onclick=()=>{drawer='objects';renderDrawer()};if($('historyTab')){$('historyTab').onclick=()=>{drawer='history';renderDrawer()};$('auditTab').onclick=()=>{drawer='audit';renderDrawer()}}document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>restoreDialog(b.dataset.restore))}
